BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET search_path=public,extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email) VALUES
('51111111-1111-4111-8111-111111111111','sharing-client@example.invalid'),
('52222222-2222-4222-8222-222222222222','sharing-coach@example.invalid'),
('53333333-3333-4333-8333-333333333333','sharing-other@example.invalid');
UPDATE profiles SET plan_tier='coach' WHERE user_id='52222222-2222-4222-8222-222222222222';
INSERT INTO coach_clients(coach_user_id,client_user_id) VALUES('52222222-2222-4222-8222-222222222222','51111111-1111-4111-8111-111111111111');
INSERT INTO baseline_audits(user_id) VALUES('51111111-1111-4111-8111-111111111111');
INSERT INTO strategic_reports(id,user_id) VALUES('5aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','51111111-1111-4111-8111-111111111111');
INSERT INTO check_ins(user_id) VALUES('51111111-1111-4111-8111-111111111111');
INSERT INTO north_star_goals(user_id,horizon,title) VALUES('51111111-1111-4111-8111-111111111111','1_year','goal');
INSERT INTO coaching_messages(user_id,role,content) VALUES('51111111-1111-4111-8111-111111111111','user','private content');
INSERT INTO plan_action_completions(user_id,report_id,phase_index,action_index) VALUES('51111111-1111-4111-8111-111111111111','5aaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',0,0);
INSERT INTO coach_annotations(coach_id,client_user_id,annotation_type,content,is_private) VALUES('52222222-2222-4222-8222-222222222222','51111111-1111-4111-8111-111111111111','note','shared',false);
INSERT INTO audit_history(user_id,audit_data) VALUES('51111111-1111-4111-8111-111111111111','{}');
INSERT INTO weekly_commitments(user_id,week_start,commitment) VALUES('51111111-1111-4111-8111-111111111111','2026-09-07','private');
INSERT INTO commitment_callbacks(user_id,check_in_id,outcome) SELECT user_id,id,'yes' FROM check_ins WHERE user_id='51111111-1111-4111-8111-111111111111';
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"52222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT is((SELECT count(*)::int FROM baseline_audits WHERE user_id='51111111-1111-4111-8111-111111111111'),1,'legacy coach can read baseline_audits');
SELECT is((SELECT count(*)::int FROM strategic_reports WHERE user_id='51111111-1111-4111-8111-111111111111'),1,'legacy coach can read strategic_reports');
SELECT is((SELECT count(*)::int FROM check_ins WHERE user_id='51111111-1111-4111-8111-111111111111'),1,'legacy coach can read check_ins');
SELECT is((SELECT count(*)::int FROM north_star_goals WHERE user_id='51111111-1111-4111-8111-111111111111'),1,'legacy coach can read north_star_goals');
SELECT is((SELECT count(*)::int FROM coaching_messages WHERE user_id='51111111-1111-4111-8111-111111111111'),1,'legacy coach can read coaching_messages');
SELECT is((SELECT count(*)::int FROM plan_action_completions WHERE user_id='51111111-1111-4111-8111-111111111111'),1,'legacy coach can read plan_action_completions');
SELECT is((SELECT count(*)::int FROM profiles WHERE user_id='51111111-1111-4111-8111-111111111111'),1,'legacy coach can read profiles');
SELECT is((SELECT count(*)::int FROM audit_history WHERE user_id='51111111-1111-4111-8111-111111111111'),1,'legacy audit history shared');
SELECT is((SELECT count(*)::int FROM weekly_commitments WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'standalone commitments never shared');
SELECT is((SELECT count(*)::int FROM commitment_callbacks WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'callbacks never shared');
SELECT set_config('request.jwt.claims','{"sub":"51111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT is((get_coach_sharing()->>'legacy')::boolean,true,'explicit legacy status');
SELECT is(jsonb_array_length(get_coach_sharing()->'coaches'),1,'actual linked coach returned');
SELECT throws_ok($$SELECT set_coach_sharing(false,false)$$,'42501',NULL,'ack required');
SELECT lives_ok($$SELECT set_coach_sharing(false,true)$$,'owner revokes');
SELECT is((get_coach_sharing()->>'enabled')::boolean,false,'readback disabled');
SELECT is((SELECT count(*)::int FROM sharing_preference_events),1,'audited');
SELECT throws_ok($$UPDATE sharing_preferences SET user_id='53333333-3333-4333-8333-333333333333'$$,'42501',NULL,'cannot reassign consent');
SELECT is((SELECT count(*)::int FROM coach_annotations WHERE client_user_id=auth.uid()),1,'shared feedback stays readable by client');
SELECT set_config('request.jwt.claims','{"sub":"52222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT is((SELECT count(*)::int FROM baseline_audits WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'revocation blocks baseline_audits');
SELECT is((SELECT count(*)::int FROM strategic_reports WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'revocation blocks strategic_reports');
SELECT is((SELECT count(*)::int FROM check_ins WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'revocation blocks check_ins');
SELECT is((SELECT count(*)::int FROM north_star_goals WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'revocation blocks north_star_goals');
SELECT is((SELECT count(*)::int FROM coaching_messages WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'revocation blocks coaching_messages');
SELECT is((SELECT count(*)::int FROM plan_action_completions WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'revocation blocks plan_action_completions');
SELECT is((SELECT count(*)::int FROM profiles WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'revocation blocks profiles');
SELECT is((SELECT count(*)::int FROM audit_history WHERE user_id='51111111-1111-4111-8111-111111111111'),0,'revocation blocks audit history');
SELECT is((SELECT count(*)::int FROM coach_annotations WHERE client_user_id='51111111-1111-4111-8111-111111111111'),0,'revocation blocks coach annotation reads');
WITH changed AS (UPDATE strategic_reports SET north_star_focus='unauthorized' WHERE user_id='51111111-1111-4111-8111-111111111111' RETURNING id) SELECT is((SELECT count(*)::int FROM changed),0,'revocation blocks report edits');
SELECT lives_ok($$SELECT set_coach_sharing(true,true)$$,'coach can only set own preference');
SELECT is(public.is_client_of(auth.uid(),'51111111-1111-4111-8111-111111111111'),false,'coach cannot enable victim');
SELECT set_config('request.jwt.claims','{"sub":"53333333-3333-4333-8333-333333333333","role":"authenticated"}',true);
SELECT is(jsonb_array_length(get_coach_sharing()->'coaches'),0,'unlinked user has no coaches');
SELECT is((SELECT count(*)::int FROM sharing_preferences),0,'cannot see victim preference');
SELECT set_config('request.jwt.claims','{"sub":"51111111-1111-4111-8111-111111111111","role":"authenticated"}',true);
SELECT lives_ok($$SELECT set_coach_sharing(true,true)$$,'owner reenables');
SELECT set_config('request.jwt.claims','{"sub":"52222222-2222-4222-8222-222222222222","role":"authenticated"}',true);
SELECT is(public.is_client_of(auth.uid(),'51111111-1111-4111-8111-111111111111'),true,'reenable effective');
RESET ROLE;
SELECT ok(NOT has_function_privilege('anon','public.set_coach_sharing(boolean,boolean)','EXECUTE'),'anonymous writes denied');
SELECT * FROM finish();
ROLLBACK;
